import type { Register } from 'claude-code'

import { addStep, emptyTally, layoutBand, resolveLocale, resolveShow, snapshotOf } from './usage'
import type { Tone } from './usage'

const tallyRef = { plugin: 'token-usage', key: 'tally' } as const
const snapshotRef = { plugin: 'token-usage', key: 'snapshot' } as const

export const register: Register = (on, options) => {
  const locale = resolveLocale(options.locale)
  const show = resolveShow(options.show)

  on('turn.step', async function* ($, e, next) {
    const result = yield* next(e)
    const { usage } = result
    if (usage === null) {
      return result
    }

    let isLanded = false
    while (!isLanded) {
      const { value, version } = await $.state.get(tallyRef)
      const written = await $.state.set(
        tallyRef,
        addStep(value ?? emptyTally(), { agentId: e.agentId, model: e.model, usage }),
        { ifVersion: version },
      )
      isLanded = written.isSet
    }
    return result
  })

  on('session.start', async ($, e, next) => {
    await $.state.set(snapshotRef, snapshotOf(await $.session.usage()))
    return next(e)
  })

  on('session.measure', async ($, e, next) => {
    await $.state.set(snapshotRef, snapshotOf(e))
    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const { value: tally } = await $.state.get(tallyRef)
    const { value: snapshot } = await $.state.get(snapshotRef)
    const lines = layoutBand(tally, snapshot, { columns: e.props.bodyColumns, locale, show, now: await $.clock.now() })

    if (e.props.hasSurvey || lines.length === 0) {
      return next(e)
    }

    const { Box, Text } = $.ui.resolve(e)

    return (
      <Box key="band" flexDirection="column">
        {lines.map((line, row) => (
          <Box key={`line${row + 1}`}>
            {line.map((segment, column) => (
              <Text key={column} {...colorOf(segment.tone)}>
                {segment.text}
              </Text>
            ))}
          </Box>
        ))}
      </Box>
    )
  })
}

function colorOf(tone: Tone): { color: string } | { dimColor: boolean } | Record<string, never> {
  if (tone === 'dim') {
    return { dimColor: true }
  }
  return tone === 'default' ? {} : { color: tone }
}

