import type {
  ClaudeUsageBucket,
  ClaudeUsageRateLimit,
  ClaudeUsageSnapshot,
  ClaudeUsageTally,
  ClaudeUsageTokens,
} from '../types'

export type Locale = 'en' | 'pt-BR'
export type Show = 'used' | 'left'
export type Severity = 'normal' | 'warn' | 'danger'
export type Tone = 'default' | 'dim' | `#${string}`
export type Segment = { text: string; tone: Tone }
export type BandLine = Segment[]

export type StepUsage = {
  input_tokens: number
  output_tokens: number
  cache_read_input_tokens: number
  cache_creation_input_tokens: number
}

export type RateLimitView = {
  label: string
  severity: Severity
  percentText: string
  fill: number
  reset?: string
  forecast?: string
  elapsed?: number
}

export type BandView = { columns: number; locale: string; now: number; show?: string }

export type BarStyle = { mark?: number; tone?: Tone }

const MAIN_BUCKET = 'main'
const MINUTE_MS = 60 * 1000
const HOUR_MS = 60 * MINUTE_MS
const DAY_MS = 24 * HOUR_MS
const BAR_COLUMNS = 80
const TWO_COLUMN_COLUMNS = 100
const SEPARATOR = ' │ '
const STACKED_BAR = 6
const MIN_BAR = 8
const MAX_BAR = 60
const COLUMN_GAP = 4
const PERCENT_WIDTH = 5
const GOOD_HIT_RATE = 70

const GREEN = '#9ece6a'
const AMBER = '#e0af68'
const RED = '#f7768e'
const AMBER_AT = 80
const MARKER = '#c0caf5'

const ROLE = {
  context: '#7aa2f7',
  cache: '#73daca',
  write: AMBER,
  cost: '#c099ff',
  window: '#7dcfff',
} as const

const FREE_WORD: Record<Locale, string> = { en: 'left', 'pt-BR': 'livre' }

const SEVERITY_TONES: Record<Severity, Tone> = { normal: GREEN, warn: AMBER, danger: RED }

const WINDOW_LABELS: Record<string, string> = { five_hour: '5h', seven_day: '7d' }

const WINDOW_LENGTHS: Record<string, number> = { five_hour: 5 * HOUR_MS, seven_day: 7 * DAY_MS }

export const resolveLocale = (value: unknown): Locale => (value === 'pt-BR' ? 'pt-BR' : 'en')

export const resolveShow = (value: unknown): Show => (value === 'left' ? 'left' : 'used')

const count = (value: number): number => (Number.isFinite(value) ? Math.max(0, value) : 0)

const emptyTokens = (): ClaudeUsageTokens => ({ input: 0, output: 0, cacheRead: 0, cacheWrite: 0 })

export const emptyTally = (): ClaudeUsageTally => ({ total: emptyTokens(), buckets: {} })

const plus = (tokens: ClaudeUsageTokens, usage: StepUsage): ClaudeUsageTokens => ({
  input: tokens.input + count(usage.input_tokens),
  output: tokens.output + count(usage.output_tokens),
  cacheRead: tokens.cacheRead + count(usage.cache_read_input_tokens),
  cacheWrite: tokens.cacheWrite + count(usage.cache_creation_input_tokens),
})

export const addStep = (
  tally: ClaudeUsageTally,
  step: { agentId?: string | undefined; model: string; usage: StepUsage },
): ClaudeUsageTally => {
  const id = step.agentId ?? MAIN_BUCKET
  const bucket: ClaudeUsageBucket = { ...plus(tally.buckets[id] ?? emptyTokens(), step.usage), model: step.model }

  return { total: plus(tally.total, step.usage), buckets: { ...tally.buckets, [id]: bucket } }
}

export const snapshotOf = (measure: {
  context: { percent?: number | undefined }
  rateLimits: readonly ClaudeUsageRateLimit[]
  cost?: { usd: number } | undefined
}): ClaudeUsageSnapshot => ({
  ...(measure.context.percent === undefined ? {} : { contextPercent: measure.context.percent }),
  ...(measure.cost === undefined ? {} : { costUsd: measure.cost.usd }),
  rateLimits: measure.rateLimits.map(limit => ({
    kind: limit.kind,
    percentUsed: limit.percentUsed,
    ...(limit.resetsAt === undefined ? {} : { resetsAt: limit.resetsAt }),
  })),
})

const withDecimal = (tenths: number, locale: Locale): string =>
  `${Math.floor(tenths / 10)}${locale === 'pt-BR' ? ',' : '.'}${tenths % 10}`

export const formatTokens = (value: number, locale: string): string => {
  const tokens = Math.round(count(value))
  if (tokens < 1000) {
    return String(tokens)
  }
  const thousandsTenths = Math.round(tokens / 100)
  if (thousandsTenths < 10000) {
    return `${withDecimal(thousandsTenths, resolveLocale(locale))}k`
  }
  return `${withDecimal(Math.round(tokens / 100000), resolveLocale(locale))}M`
}

export const formatCost = (usd: number | undefined, locale: string): string | undefined => {
  if (usd === undefined) {
    return undefined
  }
  const text = `$${count(usd).toFixed(2)}`
  return resolveLocale(locale) === 'pt-BR' ? text.replace('.', ',') : text
}

export const formatHitRate = (tokens: ClaudeUsageTokens): string => {
  const served = tokens.cacheRead + tokens.cacheWrite + tokens.input
  return served === 0 ? '—' : `${Math.round((100 * tokens.cacheRead) / served)}%`
}

export const severityOf = (percent: number): Severity => {
  if (percent >= 90) {
    return 'danger'
  }
  return percent >= 80 ? 'warn' : 'normal'
}

const formatCountdown = (ms: number): string => {
  if (ms >= DAY_MS) {
    return `${Math.floor(ms / DAY_MS)}d ${Math.floor((ms % DAY_MS) / HOUR_MS)}h`
  }
  if (ms >= HOUR_MS) {
    return `${Math.floor(ms / HOUR_MS)}h ${Math.floor((ms % HOUR_MS) / MINUTE_MS)}m`
  }
  return ms >= MINUTE_MS ? `${Math.floor(ms / MINUTE_MS)}m` : '<1m'
}

const parseInstant = (value: string | undefined): number | undefined => {
  const at = value === undefined ? Number.NaN : Date.parse(value)
  return Number.isNaN(at) ? undefined : at
}

export const formatReset = (resetsAt: string | undefined, now: number): string | undefined => {
  const at = parseInstant(resetsAt)
  return at === undefined || at <= now ? undefined : formatCountdown(at - now)
}

type WindowTiming = { elapsed: number; remaining: number; length: number }

const timingOf = (limit: ClaudeUsageRateLimit, now: number): WindowTiming | undefined => {
  const length = WINDOW_LENGTHS[limit.kind]
  const at = parseInstant(limit.resetsAt)
  if (length === undefined || at === undefined || at <= now) {
    return undefined
  }
  const elapsed = length - (at - now)
  return elapsed > 0 ? { elapsed, remaining: at - now, length } : undefined
}

/** The pace is the window's average so far; it needs no stored history. */
const forecastOf = (percent: number, timing: WindowTiming): string | undefined => {
  if (!(percent > 0 && percent < 100)) {
    return undefined
  }
  const untilHit = ((100 - percent) * timing.elapsed) / percent
  return untilHit < timing.remaining ? formatCountdown(untilHit) : undefined
}

const leftText = (percent: number, locale: Locale): string =>
  `${Math.max(0, Math.round(100 - percent))}% ${FREE_WORD[locale]}`

export const markerCell = (fraction: number, size: number, show: string): number =>
  Math.min(size, Math.max(1, Math.round((show === 'left' ? 1 - fraction : fraction) * size)))

export const describeRateLimit = (
  limit: ClaudeUsageRateLimit,
  now: number,
  locale: string,
  show: string = 'used',
): RateLimitView => {
  const reset = formatReset(limit.resetsAt, now)
  const timing = timingOf(limit, now)
  const forecast = timing === undefined ? undefined : forecastOf(limit.percentUsed, timing)
  const used = Math.min(1, Math.max(0, limit.percentUsed / 100))
  const isLeft = resolveShow(show) === 'left'

  return {
    label: WINDOW_LABELS[limit.kind] ?? limit.kind,
    severity: severityOf(limit.percentUsed),
    percentText: isLeft
      ? leftText(limit.percentUsed, resolveLocale(locale))
      : limit.percentUsed > 100
        ? '100%+'
        : `${limit.percentUsed}%`,
    fill: isLeft ? 1 - used : used,
    ...(reset === undefined ? {} : { reset }),
    ...(forecast === undefined ? {} : { forecast }),
    ...(timing === undefined ? {} : { elapsed: timing.elapsed / timing.length }),
  }
}

const channel = (hex: string, index: number): number => Number.parseInt(hex.slice(1 + 2 * index, 3 + 2 * index), 16)

const mix = (from: string, to: string, ratio: number): Tone =>
  `#${[0, 1, 2]
    .map(index => Math.round(channel(from, index) + (channel(to, index) - channel(from, index)) * ratio))
    .map(value => value.toString(16).padStart(2, '0'))
    .join('')}`

const gradientAt = (index: number, size: number): Tone => {
  const position = (index / size) * 100
  return position <= AMBER_AT
    ? mix(GREEN, AMBER, position / AMBER_AT)
    : mix(AMBER, RED, (position - AMBER_AT) / (100 - AMBER_AT))
}

/** A `mark` is the 1-based cell drawn as the marker, moved to cell 2 when it would hide the bar's only filled cell; a `tone` colors every filled cell instead of the gradient. */
export const meterBar = (fill: number, size: number, style: BarStyle = {}): BandLine => {
  const filled = fill > 0 ? Math.min(size, Math.max(1, Math.round(fill * size))) : 0
  const mark = style.mark === 1 && filled === 1 && size >= 2 ? 2 : style.mark
  const cells: BandLine = Array.from({ length: size }, (_, index) => {
    if (index + 1 === mark) {
      return { text: '┃', tone: MARKER }
    }
    return index < filled ? { text: '■', tone: style.tone ?? gradientAt(index + 1, size) } : { text: '□', tone: 'dim' }
  })

  return cells.reduce<BandLine>((line, cell) => {
    const last = line[line.length - 1]
    if (cell.text === '□' && last?.text.startsWith('□')) {
      return [...line.slice(0, -1), { ...last, text: `${last.text}□` }]
    }
    return [...line, cell]
  }, [])
}

const barFor = (fill: number, severity: Severity, size: number, show: Show, elapsed?: number): BandLine =>
  meterBar(fill, size, {
    ...(show === 'left' ? { tone: SEVERITY_TONES[severity] } : {}),
    ...(elapsed === undefined ? {} : { mark: markerCell(elapsed, size, show) }),
  })

const gap = (size: number): Segment => ({ text: ' '.repeat(size), tone: 'dim' })

const clamp = (value: number, low: number, high: number): number => Math.min(high, Math.max(low, value))

const width = (text: string): number => [...text].length

const groupWidth = (group: BandLine): number => group.reduce((sum, part) => sum + width(part.text), 0)

const truncate = (group: BandLine, limit: number): BandLine => {
  let room = Math.max(0, limit - 1)
  const kept: BandLine = []
  for (const part of group) {
    const text = [...part.text].slice(0, room).join('')
    room -= width(text)
    kept.push({ ...part, text })
  }
  const last = kept[kept.length - 1]
  return last === undefined ? [] : [...kept.slice(0, -1), { ...last, text: `${last.text}…` }]
}

const fit = (groups: BandLine[], columns: number): BandLine => {
  const kept = [...groups]
  const total = (): number => kept.reduce((sum, group) => sum + groupWidth(group), 0) + SEPARATOR.length * (kept.length - 1)
  while (kept.length > 1 && total() > columns) {
    kept.pop()
  }
  const first = kept[0]
  if (first !== undefined && kept.length === 1 && groupWidth(first) > columns) {
    kept[0] = truncate(first, columns)
  }
  return kept.flatMap((group, index) => (index === 0 ? group : [{ text: SEPARATOR, tone: 'dim' as const }, ...group]))
}

const hitTone = (tokens: ClaudeUsageTokens): Tone => {
  const served = tokens.cacheRead + tokens.cacheWrite + tokens.input
  return served > 0 && Math.round((100 * tokens.cacheRead) / served) >= GOOD_HIT_RATE ? GREEN : 'default'
}

/** A bar size of `undefined` draws no bar; 0 keeps the bar's spacing so the caller can measure the fixed text. */
const meter = (
  bar: (size: number) => BandLine,
  percentText: string,
  tone: Tone,
  size: number | undefined,
  space: number,
): BandLine => [...(size === undefined ? [] : [gap(space), ...bar(size)]), gap(space), { text: percentText, tone }]

const contextParts = (
  percent: number | undefined,
  size: number | undefined,
  space: number,
  show: Show,
  locale: Locale,
): BandLine => {
  const label: Segment = { text: '◔ ctx', tone: ROLE.context }
  if (percent === undefined) {
    return [label, gap(1), { text: '—', tone: 'default' }]
  }
  const severity = severityOf(percent)
  const isLeft = show === 'left'
  const usedText = percent > 100 ? '100%+' : `${Math.round(percent)}%`
  const fill = (isLeft ? 100 - percent : percent) / 100

  return [
    label,
    ...meter(
      length => barFor(fill, severity, length, show),
      isLeft ? leftText(percent, locale) : usedText,
      SEVERITY_TONES[severity],
      size,
      space,
    ),
  ]
}

const cacheParts = (tokens: ClaudeUsageTokens, locale: Locale, isDotted: boolean): BandLine => {
  const joiner: Segment = isDotted ? { text: ' · ', tone: 'dim' } : gap(1)
  return [
    { text: '↻ cache', tone: ROLE.cache },
    gap(1),
    { text: `R ${formatTokens(tokens.cacheRead, locale)}`, tone: ROLE.cache },
    joiner,
    { text: `W ${formatTokens(tokens.cacheWrite, locale)}`, tone: ROLE.write },
    joiner,
    { text: `◎ ${formatHitRate(tokens)}`, tone: hitTone(tokens) },
  ]
}

const windowParts = (
  limit: ClaudeUsageRateLimit,
  view: BandView,
  show: Show,
  size: number | undefined,
  space: number,
): BandLine => {
  const described = describeRateLimit(limit, view.now, view.locale, show)

  return [
    { text: `◷ ${described.label}`, tone: ROLE.window },
    ...meter(
      length => barFor(described.fill, described.severity, length, show, described.elapsed),
      described.percentText,
      SEVERITY_TONES[described.severity],
      size,
      space,
    ),
    ...(described.forecast === undefined ? [] : [gap(space), { text: `↯ ${described.forecast}`, tone: RED }]),
    ...(described.reset === undefined ? [] : [gap(space), { text: `↺ ${described.reset}`, tone: 'dim' as const }]),
  ]
}

const stacked = (
  tally: ClaudeUsageTally,
  snapshot: ClaudeUsageSnapshot | undefined,
  view: BandView,
  show: Show,
): BandLine[] => {
  const locale = resolveLocale(view.locale)
  const size = view.columns >= BAR_COLUMNS ? STACKED_BAR : undefined
  const cost = formatCost(snapshot?.costUsd, locale)
  const usage: BandLine[] = [
    contextParts(snapshot?.contextPercent, size, 1, show, locale),
    cacheParts(tally.total, locale, false),
    ...(cost === undefined ? [] : [[{ text: cost, tone: ROLE.cost }]]),
  ]
  const limits = snapshot?.rateLimits ?? []

  return [
    fit(usage, view.columns),
    ...(limits.length === 0 ? [] : [fit(limits.map(limit => windowParts(limit, view, show, size, 1)), view.columns)]),
  ]
}

const textWidth = (text: string): number => [...text].length

const widest = (texts: readonly string[]): number => Math.max(0, ...texts.map(textWidth))

const optionalColumn = (columnWidth: number, text: string, tone: Tone): BandLine => {
  if (columnWidth === 0) {
    return []
  }
  return text === '' ? [gap(2 + columnWidth)] : [gap(2), { text, tone }, gap(columnWidth - textWidth(text))]
}

const windowTable = (
  limits: readonly ClaudeUsageRateLimit[],
  view: BandView,
  show: Show,
  room: number,
): BandLine[] | undefined => {
  const rows = limits.map(limit => describeRateLimit(limit, view.now, view.locale, show))
  const labels = rows.map(row => `◷ ${row.label}`)
  const forecasts = rows.map(row => (row.forecast === undefined ? '' : `↯ ${row.forecast}`))
  const resets = rows.map(row => (row.reset === undefined ? '' : `↺ ${row.reset}`))
  const labelWidth = widest(labels)
  const percentWidth = Math.max(PERCENT_WIDTH, widest(rows.map(row => row.percentText)))
  const forecastWidth = widest(forecasts)
  const resetWidth = widest(resets)
  const fixed =
    labelWidth +
    2 +
    2 +
    percentWidth +
    (forecastWidth === 0 ? 0 : 2 + forecastWidth) +
    (resetWidth === 0 ? 0 : 2 + resetWidth)
  if (rows.length > 0 && room - fixed < MIN_BAR) {
    return undefined
  }
  const size = clamp(room - fixed, MIN_BAR, MAX_BAR)

  return rows.map((row, index) => [
    { text: labels[index] ?? '', tone: ROLE.window },
    gap(labelWidth - textWidth(labels[index] ?? '') + 2),
    ...barFor(row.fill, row.severity, size, show, row.elapsed),
    gap(2 + percentWidth - textWidth(row.percentText)),
    { text: row.percentText, tone: SEVERITY_TONES[row.severity] },
    ...optionalColumn(forecastWidth, forecasts[index] ?? '', RED),
    ...optionalColumn(resetWidth, resets[index] ?? '', 'dim'),
  ])
}

const twoColumns = (
  tally: ClaudeUsageTally,
  snapshot: ClaudeUsageSnapshot | undefined,
  view: BandView,
  show: Show,
): BandLine[] | undefined => {
  const { columns } = view
  const locale = resolveLocale(view.locale)
  const percent = snapshot?.contextPercent
  const limits = snapshot?.rateLimits ?? []
  const cost = formatCost(snapshot?.costUsd, locale)

  const contextFixed = groupWidth(contextParts(percent, percent === undefined ? undefined : 0, 2, show, locale))
  const cacheLine: BandLine = [
    ...cacheParts(tally.total, locale, true),
    ...(cost === undefined ? [] : [gap(2), { text: cost, tone: ROLE.cost }]),
  ]
  const leftWidth = Math.floor((columns - COLUMN_GAP) / 2)
  const needed = Math.max(contextFixed + (percent === undefined ? 0 : MIN_BAR), groupWidth(cacheLine))
  if (needed > leftWidth) {
    return undefined
  }

  const contextBar = percent === undefined ? undefined : clamp(leftWidth - contextFixed, MIN_BAR, MAX_BAR)
  const lefts = [contextParts(percent, contextBar, 2, show, locale), cacheLine]
  const leftEnd = Math.max(...lefts.map(groupWidth))
  const rights = windowTable(limits, view, show, columns - COLUMN_GAP - leftEnd)
  if (rights === undefined) {
    return undefined
  }

  return Array.from({ length: Math.max(lefts.length, rights.length) }, (_, row) => {
    const left = lefts[row] ?? []
    const right = rights[row]
    if (right === undefined) {
      return left
    }
    const trailing = columns - leftEnd - COLUMN_GAP - groupWidth(right)
    return [...left, gap(leftEnd - groupWidth(left) + COLUMN_GAP), ...right, ...(trailing > 0 ? [gap(trailing)] : [])]
  })
}

export const layoutBand = (
  tally: ClaudeUsageTally | undefined,
  snapshot: ClaudeUsageSnapshot | undefined,
  view: BandView,
): BandLine[] => {
  const hasData = snapshot !== undefined || Object.keys(tally?.buckets ?? {}).length > 0
  if (!hasData) {
    return []
  }
  const held = tally ?? emptyTally()
  const show = resolveShow(view.show)
  return (
    (view.columns >= TWO_COLUMN_COLUMNS ? twoColumns(held, snapshot, view, show) : undefined) ??
    stacked(held, snapshot, view, show)
  )
}

