export type ClaudeUsageTokens = {
  input: number
  output: number
  cacheRead: number
  cacheWrite: number
}

export type ClaudeUsageBucket = ClaudeUsageTokens & { model: string }

export type ClaudeUsageTally = {
  total: ClaudeUsageTokens
  buckets: Record<string, ClaudeUsageBucket>
}

export type ClaudeUsageRateLimit = {
  kind: string
  percentUsed: number
  resetsAt?: string
}

export type ClaudeUsageSnapshot = {
  contextPercent?: number
  costUsd?: number
  rateLimits: ClaudeUsageRateLimit[]
}

declare module 'claude-code' {
  interface PluginState {
    'token-usage': {
      tally: ClaudeUsageTally
      snapshot: ClaudeUsageSnapshot
    }
  }
}
